import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.BgSoyxN5.js";const g=JSON.parse('{"title":"TickerForge FAQ | Portfolio Analytics and Stress Testing Questions","description":"Frequently asked questions about TickerForge including portfolio imports, broker integrations, stress testing, data sources, and platform security.","frontmatter":{"title":"TickerForge FAQ | Portfolio Analytics and Stress Testing Questions","description":"Frequently asked questions about TickerForge including portfolio imports, broker integrations, stress testing, data sources, and platform security."},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1783255719000}'),s={name:"faq.md"};function i(n,e,l,d,c,u){return a(),o("div",null,e[0]||(e[0]=[t('<h1 id="❓-frequently-asked-questions" tabindex="-1">❓ Frequently Asked Questions <a class="header-anchor" href="#❓-frequently-asked-questions" aria-label="Permalink to &quot;❓ Frequently Asked Questions&quot;">​</a></h1><hr><h3 id="is-tickerforge-a-brokerage-can-i-trade-here" tabindex="-1">Is TickerForge a brokerage? Can I trade here? <a class="header-anchor" href="#is-tickerforge-a-brokerage-can-i-trade-here" aria-label="Permalink to &quot;Is TickerForge a brokerage? Can I trade here?&quot;">​</a></h3><p>No. <strong>TickerForge is a portfolio analytics and intelligence platform.</strong> We do not execute trades, hold funds, or move capital. You use TickerForge to analyze, stress-test, and diagnose your investments. All actual trading remains securely at your existing broker.</p><hr><h3 id="how-do-i-import-my-portfolio" tabindex="-1">How do I import my portfolio? <a class="header-anchor" href="#how-do-i-import-my-portfolio" aria-label="Permalink to &quot;How do I import my portfolio?&quot;">​</a></h3><p>You can import your holdings in three ways:</p><ol><li><strong>Broker Sync (Beta):</strong> Read-only connection for Interactive Brokers (IBKR) and Webull.</li><li><strong>CSV Upload:</strong> Export your positions from any broker and upload them.</li><li><strong>Manual / Mock Mode:</strong> Build a portfolio manually to test strategies.</li></ol><hr><h3 id="is-my-brokerage-data-safe" tabindex="-1">Is my brokerage data safe? <a class="header-anchor" href="#is-my-brokerage-data-safe" aria-label="Permalink to &quot;Is my brokerage data safe?&quot;">​</a></h3><p>Absolutely. We use <strong>read-only access</strong> for broker integrations. We do <strong>not</strong> collect brokerage credentials (passwords), account numbers, or personal identity data. Your portfolio holdings are stored securely solely to generate your health scores and stress tests. You can delete your imported balances from our servers at any time with one click.</p><hr><h3 id="where-does-the-fundamental-data-come-from" tabindex="-1">Where does the fundamental data come from? <a class="header-anchor" href="#where-does-the-fundamental-data-come-from" aria-label="Permalink to &quot;Where does the fundamental data come from?&quot;">​</a></h3><p>Unlike many retail tools that rely on delayed or aggregated data, TickerForge focuses on <strong>Data Integrity</strong>. Our fundamental metrics are sourced directly from raw <strong>SEC/EDGAR filings</strong> and reputable institutional data providers to ensure accuracy for DCF modeling and risk scoring.</p><hr><h3 id="what-is-the-stress-test-feature" tabindex="-1">What is the &quot;Stress Test&quot; feature? <a class="header-anchor" href="#what-is-the-stress-test-feature" aria-label="Permalink to &quot;What is the &quot;Stress Test&quot; feature?&quot;">​</a></h3><p>The Stress Test engine (available for imported portfolios) simulates market shocks. For example, if the S&amp;P 500 drops 10%, our beta-weighted algorithm calculates your estimated drawdown. Crucially, if you use margin or short selling, it estimates your <strong>Maintenance Margin</strong> under stress, warning you of potential Margin Calls <em>before</em> your broker does.</p><hr><h3 id="does-it-cover-crypto-or-forex" tabindex="-1">Does it cover Crypto or Forex? <a class="header-anchor" href="#does-it-cover-crypto-or-forex" aria-label="Permalink to &quot;Does it cover Crypto or Forex?&quot;">​</a></h3><p>Currently, our active universe focuses on <strong>U.S. equities and ETFs</strong> (3,000+ active tickers with Cap &gt; $200M). We also track global <strong>Macro indicators</strong> (VIX, DXY, US Treasuries). Crypto is not included in the current core release.</p><hr><h3 id="do-you-provide-trade-recommendations-or-advisory-services" tabindex="-1">Do you provide trade recommendations or advisory services? <a class="header-anchor" href="#do-you-provide-trade-recommendations-or-advisory-services" aria-label="Permalink to &quot;Do you provide trade recommendations or advisory services?&quot;">​</a></h3><p>No. TickerForge provides software-generated research outputs and monitoring alerts for educational workflows. These are mathematical flags based on available market data, company data, SEC filings, and volume trends. They are designed for independent research, not as recommendations to buy or sell.</p><hr><h3 id="do-i-need-to-install-an-app" tabindex="-1">Do I need to install an app? <a class="header-anchor" href="#do-i-need-to-install-an-app" aria-label="Permalink to &quot;Do I need to install an app?&quot;">​</a></h3><p>No. TickerForge runs entirely through a <strong>Telegram Web App</strong>. It gives you a desktop-grade analytics dashboard directly inside your mobile messenger.</p><hr><h3 id="can-i-try-it-for-free" tabindex="-1">Can I try it for free? <a class="header-anchor" href="#can-i-try-it-for-free" aria-label="Permalink to &quot;Can I try it for free?&quot;">​</a></h3><p>Yes. The <strong>Free plan</strong> allows you to explore the active stock universe, use the mock trading sandbox, and view basic reports. Advanced features like full Portfolio Stress Testing and unlimited DCF analyses are available on the Pro plan.<br> 👉 <a href="/pricing">View Pricing Plans</a></p>',29)]))}const m=r(s,[["render",i]]);export{g as __pageData,m as default};
